import heapq

def johnson(n={{n}}, edges={{edges}}):
    aug = edges + [(n, v, 0) for v in range(n)]
    INF = float('inf'); h = [0]*(n+1)
    for _ in range(n):
        for u, v, w in aug:
            if h[u]+w < h[v]: h[v] = h[u]+w
    for u, v, w in aug:
        if h[u]+w < h[v]: return None
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w + h[u] - h[v]))
    apsp = []
    for s in range(n):
        d = [INF]*n; d[s] = 0; pq = [(0, s)]
        while pq:
            du, u = heapq.heappop(pq)
            if du > d[u]: continue
            for v, w in adj[u]:
                if du+w < d[v]: d[v] = du+w; heapq.heappush(pq, (d[v], v))
        apsp.append([d[v] - h[s] + h[v] if d[v] < INF else INF for v in range(n)])
    return apsp
